{
  "version": "Notebook/1.0",
  "items": [
    {
      "type": 1,
      "content": {
        "json": "# Application Insights — End-to-End Agent Investigation\nFollow customer impact from browser and request telemetry through agent, model, handoff, tool, retry, and semantic task outcomes. All lab data is synthetic and prompt/completion content recording remains disabled."
      },
      "name": "title"
    },
    {
      "type": 9,
      "content": {
        "version": "KqlParameterItem/1.0",
        "parameters": [
          {
            "id": "p-timerange",
            "version": "KqlParameterItem/1.0",
            "name": "TimeRange",
            "label": "Time range",
            "type": 4,
            "isRequired": true,
            "value": { "durationMs": 86400000 },
            "typeSettings": {
              "selectableValues": [
                { "durationMs": 3600000 },
                { "durationMs": 14400000 },
                { "durationMs": 86400000 },
                { "durationMs": 604800000 }
              ],
              "allowCustom": true
            }
          },
          {
            "id": "p-appinsights",
            "version": "KqlParameterItem/1.0",
            "name": "AppInsights",
            "label": "Application Insights",
            "type": 5,
            "isRequired": true,
            "multiSelect": false,
            "quote": "'",
            "resourceType": "microsoft.insights/components",
            "typeSettings": {
              "resourceTypeFilter": { "microsoft.insights/components": true }
            },
            "value": "__APPINSIGHTS_ID__"
          }
        ],
        "style": "pills",
        "queryType": 0,
        "resourceType": "microsoft.insights/components"
      },
      "name": "parameters"
    },
    {
      "type": 1,
      "content": { "json": "## Detect and scope\nTechnical success, task correctness, performance budgets, and trace completeness are independent health dimensions." },
      "name": "detect-heading"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "dependencies | where type == 'GenAI' and name == 'customer_support_agent' | extend Scenario=tostring(customDimensions['scenario']), Mode=tostring(customDimensions['demo.mode']), Technical=tostring(customDimensions['technical.success']), Task=tostring(customDimensions['task.success']), Performance=tostring(customDimensions['performance.success']), Trace=tostring(customDimensions['trace.complete']) | summarize Runs=count(), TechnicalFailures=countif(Technical=='false'), TaskFailures=countif(Task=='false'), PerformanceFailures=countif(Performance=='false'), IncompleteTraces=countif(Trace=='false'), P95DurationMs=percentile(duration,95) by Scenario, Mode | order by Scenario asc, Mode asc",
        "size": 0,
        "title": "Agent task health",
        "timeContextFromParameter": "TimeRange",
        "queryType": 0,
        "resourceType": "microsoft.insights/components",
        "crossComponentResources": [ "{AppInsights}" ],
        "visualization": "table"
      },
      "name": "agent-task-health"
    },
    {
      "type": 1,
      "content": { "json": "## Compare broken and fixed profiles\nA fix is proven only when the same outcome, latency, retry, token, and trace-quality measurements recover." },
      "name": "compare-heading"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "dependencies | where type == 'GenAI' and name == 'customer_support_agent' | extend Scenario=tostring(customDimensions['scenario']), Mode=tostring(customDimensions['demo.mode']), Task=tostring(customDimensions['task.success'])=='true', Performance=tostring(customDimensions['performance.success'])=='true', Retries=toint(customDimensions['retry.count']), InputTokens=toint(customDimensions['gen_ai.usage.input_tokens']) | summarize Runs=count(), TaskSuccessRate=100.0*countif(Task)/count(), PerformanceSuccessRate=100.0*countif(Performance)/count(), P95DurationMs=percentile(duration,95), AvgRetries=avg(Retries), AvgInputTokens=avg(InputTokens) by Scenario, Mode | order by Scenario asc, Mode asc",
        "size": 0,
        "title": "Broken versus fixed evidence",
        "timeContextFromParameter": "TimeRange",
        "queryType": 0,
        "resourceType": "microsoft.insights/components",
        "crossComponentResources": [ "{AppInsights}" ],
        "visualization": "table"
      },
      "name": "broken-fixed"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "dependencies | where type == 'GenAI' and name == 'customer_support_agent' | extend Scenario=tostring(customDimensions['scenario']), Mode=tostring(customDimensions['demo.mode']), Retries=toint(customDimensions['retry.count']), InputTokens=toint(customDimensions['gen_ai.usage.input_tokens']), OutputTokens=toint(customDimensions['gen_ai.usage.output_tokens']), Task=tostring(customDimensions['task.success']) | summarize Runs=count(), SuccessfulRuns=countif(Task=='true'), Retries=sum(Retries), Tokens=sum(InputTokens)+sum(OutputTokens) by Scenario, Mode | extend TokensPerSuccessfulTask=iff(SuccessfulRuns>0,todouble(Tokens)/SuccessfulRuns,real(null)) | order by TokensPerSuccessfulTask desc nulls last",
        "size": 0,
        "title": "Retry and token efficiency",
        "timeContextFromParameter": "TimeRange",
        "queryType": 0,
        "resourceType": "microsoft.insights/components",
        "crossComponentResources": [ "{AppInsights}" ],
        "visualization": "table"
      },
      "name": "retry-token-efficiency"
    },
    {
      "type": 1,
      "content": { "json": "## Validate the customer function\nThe task-level availability test checks the deterministic fixed agent path, not only the web server root." },
      "name": "availability-heading"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "availabilityResults | summarize Runs=count(), Failures=countif(success==false), AvailabilityPct=100.0*countif(success==true)/count(), P95DurationMs=percentile(duration,95) by name, location | order by name asc, location asc",
        "size": 0,
        "title": "Root and agent-task availability",
        "timeContextFromParameter": "TimeRange",
        "queryType": 0,
        "resourceType": "microsoft.insights/components",
        "crossComponentResources": [ "{AppInsights}" ],
        "visualization": "table"
      },
      "name": "task-availability"
    }
  ],
  "styleSettings": {},
  "$schema": "https://github.com/Microsoft/Application-Insights-Workbooks/blob/master/schema/workbook.json"
}

